import os,re,json
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load()

def solve(g):
    h,w=len(g),len(g[0])
    from collections import Counter
    cnt=Counter(x for r in g for x in r)
    bg=cnt.most_common(1)[0][0]
    blkc=max((c for c in cnt if c!=bg), key=lambda c:cnt[c])
    brs=[r for r in range(h) for x in g[r] if x==blkc]; bcs=[c for r in range(h) for c in range(w) if g[r][c]==blkc]
    br0=min(brs); br1=max(brs); bc0=min(bcs); bc1=max(bcs)
    out=[r[:] for r in g]
    for r in range(h):
        for c in range(w):
            v=g[r][c]
            if v==bg or v==blkc: continue
            # marker: copy onto block edge along its axis
            if bc0<=c<=bc1:
                nr = br0 if r<br0 else br1
                out[nr][c]=v
            elif br0<=r<=br1:
                nc = bc0 if c<bc0 else bc1
                out[r][nc]=v
    return out

for k in ['Demo pair 1','Demo pair 2','Demo pair 3']:
    i,o=G[k+' input'],G[k+' output']
    p=solve(i)
    print(k, 'match:', p==o)
    if p!=o:
        for a in range(len(o)):
            if p[a]!=o[a]: print(a,'got',p[a],'want',o[a])
